practice.solution:
package main

import "fmt"

type Payer interface {
	Pay(amount int) string
}

type Cash struct{}

type Card struct {
	Last4 string
	Uses  int
}

func (c Cash) Pay(amount int) string {
	return fmt.Sprintf("paid %d in cash", amount)
}

func (c *Card) Pay(amount int) string {
	c.Uses++
	return fmt.Sprintf("paid %d with card %s", amount, c.Last4)
}

func checkout(p Payer, amount int) {
	fmt.Println(p.Pay(amount))
}

func main() {
	card := Card{Last4: "4242"}
	checkout(Cash{}, 20)
	checkout(&card, 15)
	checkout(&card, 40)
	checkout(&card, 5)
	fmt.Printf("card uses: %d\n", card.Uses)
}

steps.body:
The fmt package declares a one-method interface:

```go
type Stringer interface {
	String() string
}
```

Give a type a `String()` method and `fmt.Println`, `%v`, and `%s` call it for you, even for values inside a slice. That is how an iota enum prints `Green` instead of `1`, while `%d` still prints the number.

```go
func (c Color) String() string {
	switch c {
	case Red:
		return "Red"
	}
	return fmt.Sprintf("Color(%d)", int(c))
}
```

Two gotchas:

- Inside `String`, format the fields or a plain conversion such as `int(c)`, never the value itself. `fmt.Sprintf("%v", c)` calls `String` again, which calls `Sprintf` again, until the stack runs out and the program crashes.
- Watch the receiver. A `String` on `*Point` runs only when you print a `*Point`. Printing a plain `Point` falls back to `{3 4}`. A type whose methods all use value receivers, like `Color` here, gets a value-receiver `String` too.

example.code:
package main

import "fmt"

type Color int

const (
	Red Color = iota
	Green
	Blue
)

func (c Color) String() string {
	switch c {
	case Red:
		return "Red"
	case Green:
		return "Green"
	case Blue:
		return "Blue"
	}
	return fmt.Sprintf("Color(%d)", int(c)) // int(c) has no String method
}

func main() {
	fmt.Println(Green)
	fmt.Println([]Color{Blue, Red})
	fmt.Printf("%v is number %d\n", Blue, Blue)
	fmt.Println(Color(7))
}

