package main

import "fmt"

type Point struct{ X, Y int }

func (p Point) String() string {
	return fmt.Sprintf("(%d, %d)", p.X, p.Y)
}

func main() {
	p := Point{X: 3, Y: 4}
	fmt.Println(p)
	fmt.Println([]Point{{X: 1, Y: 2}, {X: 3, Y: 4}})
	fmt.Printf("moved from %v to %v\n", Point{}, p)
}

