package main

import "fmt"

func main() {
	var a interface{} = 3
	var b interface{} = 3.0
	fmt.Printf("%T %T\n", a, b)

	vals := []interface{}{3, "four", 5, 6.5, 7}
	word := vals[1].(string) // panics if vals[1] is not a string
	fmt.Printf("%s has %d letters\n", word, len(word))

	var sum int
	for _, v := range vals {
		if n, ok := v.(int); ok {
			sum += n
		}
	}
	fmt.Printf("Sum of ints: %d\n", sum)
}

