practice.solution:
package main

import (
	"fmt"
	"strings"
)

func main() {
	var a interface{} = 'x'
	var b interface{} = "x"
	fmt.Printf("%T %T\n", a, b)

	vals := []interface{}{"go", 1, "is", true, "fun"}
	first := vals[0].(string)
	fmt.Printf("%s has %d letters\n", first, len(first))

	var words []string
	for _, v := range vals {
		if s, ok := v.(string); ok {
			words = append(words, s)
		}
	}
	fmt.Println(strings.Join(words, " "))
}
